/* ============================================================
   Nullpoint — Privacy-First Analytics
   Swiss Modern design system
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --void: #0A0A0A;
  --white: #F5F5F5;
  --signal: #E5001A;
  --slate: #4A4A4A;
  --grid: #DEDEDE;
  --mist: #F0F0F0;
  --ink: #1A1A2E;
  --verified: #00875A;
  --ink-soft: #1E2240;
  --dark-rule: #2E2E4A;

  --font-heading: 'Archivo', system-ui, -apple-system, Segoe UI, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, Segoe UI, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, Menlo, Consolas, monospace;

  --max-width: 1280px;
  --page-pad: 80px;
  --nav-height: 64px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--white);
  color: var(--void);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding-top: var(--nav-height);
}

a {
  color: inherit;
  text-decoration: none;
}

img,
svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
}

/* ============================================================
   Layout
   ============================================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-left: var(--page-pad);
  padding-right: var(--page-pad);
}

.section {
  padding-top: 96px;
  padding-bottom: 96px;
  position: relative;
}

.section--mist  { background: var(--mist); }
.section--white { background: var(--white); }
.section--ink   { background: var(--ink); color: var(--white); }
.section--void  { background: var(--void); color: var(--white); }

.section__rule-top {
  border-top: 1px solid var(--grid);
}
.section__rule-bottom {
  border-bottom: 1px solid var(--grid);
}

/* ============================================================
   Typography helpers
   ============================================================ */

.eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--signal);
  margin: 0 0 16px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.eyebrow--centered {
  display: flex;
  justify-content: center;
}

.eyebrow--bar::before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 2px;
  background: var(--signal);
}

.eyebrow--slate { color: var(--slate); }

.headline-display {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 72px;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin: 0;
  color: var(--void);
}

.headline-section {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 48px;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0;
  color: var(--void);
}

.headline-section--white { color: var(--white); }
.headline-section--xl { font-size: 56px; font-weight: 800; }
.headline-section--md { font-size: 40px; }
.headline-section--sm { font-size: 36px; }

.subheadline {
  font-family: var(--font-body);
  font-size: 18px;
  line-height: 1.65;
  color: var(--slate);
  margin: 24px 0 0;
  max-width: 60ch;
}

.subheadline--white { color: #C8C8C8; }
.subheadline--mute { color: #9A9A9A; }

.body-prose {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--slate);
  max-width: 68ch;
}

.body-prose--white { color: #B0B0B0; }
.body-prose code,
.body-prose .mono-inline {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--void);
  background: transparent;
}

/* ============================================================
   CTA buttons & links
   ============================================================ */

.cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 40px;
}

.cta-row--center {
  justify-content: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  height: 48px;
  padding: 0 24px;
  border: 1.5px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}

.btn--primary {
  background: var(--signal);
  color: #fff;
  border-color: var(--signal);
}
.btn--primary:hover { background: #FF1A30; border-color: #FF1A30; }

.btn--secondary {
  background: transparent;
  color: var(--void);
  border-color: var(--void);
}
.btn--secondary:hover { color: var(--signal); border-color: var(--signal); }

.btn--ghost-light {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn--ghost-light:hover { color: var(--signal); border-color: var(--signal); }

.btn--ghost-grid {
  background: transparent;
  color: var(--white);
  border-color: var(--grid);
}
.btn--ghost-grid:hover { color: var(--signal); border-color: var(--signal); }

.btn--lg { height: 52px; padding: 0 32px; min-width: 180px; }
.btn--block { width: 100%; }

.text-link {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 14px;
  color: var(--void);
  border-bottom: 1px solid var(--void);
  padding-bottom: 2px;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  white-space: nowrap;
}
.text-link__arrow { color: var(--signal); }
.text-link:hover { border-color: var(--signal); }

.editorial-link {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 15px;
  color: var(--signal);
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.editorial-link:hover { border-bottom-color: var(--signal); }
.editorial-link__arrow {
  font-family: var(--font-mono);
}

/* ============================================================
   Navigation
   ============================================================ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: var(--void);
  border-bottom: 1px solid var(--grid);
  z-index: 1000;
}

.nav__inner {
  height: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--white);
  font-size: 18px;
  letter-spacing: -0.01em;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.nav__logo-mark {
  width: 18px;
  height: 18px;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
  margin-left: auto;
}

.nav__link {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--white);
  padding: 6px 0;
  border-bottom: 1px solid transparent;
  transition: border-color 0.15s ease, color 0.15s ease;
}

.nav__link:hover { border-bottom-color: var(--signal); }
.nav__link.is-active { border-bottom-color: var(--signal); color: var(--white); }

.nav__cta {
  margin-left: 12px;
  background: var(--signal);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 9px 16px;
  border: 0;
  border-radius: 999px;
}

.nav__cta:hover { background: #FF1A30; }

.nav__toggle {
  display: none;
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
  padding: 6px 10px;
  font-family: var(--font-mono);
  font-size: 12px;
  cursor: pointer;
  margin-left: auto;
}

/* ============================================================
   Hero (home)
   ============================================================ */

.hero {
  background: var(--white);
  padding-top: 120px;
  padding-bottom: 96px;
  border-bottom: 1px solid var(--grid);
}

.hero__grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 64px;
  align-items: center;
}

.hero__copy { max-width: 600px; }

.hero__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 72px;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin: 0;
}

.hero__sub {
  margin-top: 24px;
  max-width: 520px;
  font-size: 18px;
  color: var(--slate);
}

/* Hero illustration (analytics dashboard mock) */
.hero-mock {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
  display: grid;
  gap: 16px;
}

.hero-mock__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
  border-bottom: 1px solid var(--grid);
  padding-bottom: 12px;
}

.hero-mock__head strong {
  color: var(--void);
  font-weight: 700;
}

.hero-mock__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.hero-mock__metric {
  border: 1px solid var(--grid);
  padding: 10px 12px;
}

.hero-mock__metric .num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 18px;
  color: var(--void);
  display: block;
}

.hero-mock__metric .lbl {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--slate);
}

.hero-mock__metric--accent .num { color: var(--signal); }

.hero-mock__chart {
  border: 1px solid var(--grid);
  padding: 16px 18px 12px;
}

.hero-mock__chart-title {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--slate);
  margin-bottom: 12px;
  display: flex;
  justify-content: space-between;
}

.hero-mock__chart-title em {
  font-style: normal;
  color: var(--signal);
  font-weight: 700;
}

.hero-mock__funnel {
  display: grid;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
}

.hero-mock__bar {
  position: relative;
  height: 22px;
  background: var(--mist);
  border-left: 2px solid var(--signal);
}

.hero-mock__bar > span {
  position: absolute;
  inset: 0 auto 0 0;
  background: rgba(229,0,26,0.12);
}

.hero-mock__bar > b {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--void);
  font-weight: 700;
}

/* ============================================================
   Stats
   ============================================================ */

.stats {
  background: var(--mist);
  border-top: 1px solid var(--grid);
  border-bottom: 1px solid var(--grid);
  padding-top: 80px;
  padding-bottom: 80px;
}

.stats__head { text-align: center; }
.stats__head .eyebrow { justify-content: center; display: flex; }
.stats__head .headline-section--sm { margin: 8px auto 0; }
.stats__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 56px;
  border-top: 1px solid var(--grid);
}

.stat {
  padding: 32px;
  border-right: 1px solid var(--grid);
  border-bottom: 1px solid var(--grid);
}
.stat:last-child { border-right: 0; }

.stat__num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 48px;
  color: var(--void);
  letter-spacing: -0.01em;
  line-height: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat__num--signal { color: var(--signal); }
.stat__num--verified { color: var(--verified); font-size: 28px; }

.stat__num svg { flex-shrink: 0; }

.stat__desc {
  margin-top: 12px;
  font-size: 14px;
  color: var(--slate);
  line-height: 1.5;
  font-family: var(--font-body);
}

/* Dark stats variant (enterprise) */
.stats-dark {
  background: var(--void);
  color: var(--white);
}

.stats-dark .stats__head { text-align: left; }
.stats-dark .stats__head .eyebrow { display: inline-flex; }
.stats-dark .stats__grid {
  border: 0;
  margin-top: 48px;
  grid-template-columns: repeat(4, 1fr);
}

.stats-dark .stat {
  border-right: 1px solid var(--slate);
  border-bottom: 0;
}
.stats-dark .stat:last-child { border-right: 0; }

.stats-dark .stat__num {
  color: var(--white);
  font-size: 56px;
}
.stats-dark .stat__desc { color: var(--grid); }

/* ============================================================
   Feature grid
   ============================================================ */

.features-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 32px;
  margin-bottom: 56px;
}

.features-head__title { max-width: 640px; }
.features-head__title .headline-section { margin-top: 8px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
}

.feature-grid--two {
  grid-template-columns: repeat(2, 1fr);
}

.feature-card {
  background: var(--white);
  border: 2px solid var(--grid);
  padding: 32px;
  position: relative;
  margin-left: -1px;
  margin-top: -1px;
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 2px;
  height: 32px;
  background: var(--signal);
}

.feature-card--lead::before { height: 48px; }

.feature-card__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.01em;
  color: var(--void);
  margin: 16px 0 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.feature-card__title .verified-dot {
  width: 8px;
  height: 8px;
  background: var(--verified);
  border-radius: 50%;
  display: inline-block;
}

.feature-card__desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--slate);
  margin: 8px 0 0;
}

.code-chip {
  display: inline-block;
  margin-top: 16px;
  padding: 6px 10px;
  background: var(--mist);
  border: 1px solid var(--grid);
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
}

/* Feature card with tag (features page) */
.feature-card--tagged {
  border: 1px solid var(--grid);
  background: var(--white);
}
.feature-card--tagged::before { display: none; }

.tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--signal);
  border: 1px solid var(--signal);
  border-radius: 2px;
  padding: 4px 8px;
  margin-bottom: 16px;
}

.tag--verified {
  color: var(--verified);
  border-color: var(--verified);
}

/* Compliance feature card with icon */
.feature-card--icon {
  border: 1px solid var(--grid);
  background: var(--white);
}
.feature-card--icon::before { display: none; }

.feature-card__icon {
  width: 32px;
  height: 32px;
  margin-bottom: 16px;
  color: var(--void);
}

/* ============================================================
   Testimonials
   ============================================================ */

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--mist);
  border: 1px solid var(--grid);
  padding: 32px;
}

.testimonial-card__quote-mark {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 64px;
  color: var(--signal);
  line-height: 1;
  margin-bottom: -8px;
  display: block;
}

.testimonial-card__quote {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  color: var(--void);
  font-style: italic;
  margin: 0;
}

.testimonial-card__divider {
  border: 0;
  border-top: 1px solid var(--grid);
  margin: 24px 0 16px;
}

.testimonial-card__attr {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--slate);
  margin: 0;
}

.testimonial-card__attr strong {
  color: var(--slate);
  font-weight: 600;
  display: block;
}

/* ============================================================
   CTA panel (dark)
   ============================================================ */

.cta-panel {
  background: var(--ink);
  color: var(--white);
  padding-top: 112px;
  padding-bottom: 112px;
  position: relative;
  overflow: hidden;
}

.cta-panel--pattern::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(245,245,245,0.10) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
}

.cta-panel__inner {
  position: relative;
  text-align: center;
}

.cta-panel__inner .eyebrow {
  display: flex;
  justify-content: center;
}

.cta-panel__head {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 56px;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--white);
  max-width: 720px;
  margin: 8px auto 0;
}

.cta-panel__sub {
  margin: 16px auto 0;
  max-width: 480px;
  color: #A0A0B8;
  font-size: 16px;
}

.cta-panel__cta-row {
  margin-top: 48px;
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

/* Footer strip inside ink panel */
.footer-strip {
  position: relative;
  margin-top: 64px;
  padding-top: 24px;
  border-top: 1px solid rgba(222,222,222,0.2);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}

.footer-strip__brand {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--white);
}

.footer-strip__links {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
  text-align: center;
}

.footer-strip__links a {
  color: var(--grid);
  border-bottom: 1px solid transparent;
}
.footer-strip__links a:hover { border-bottom-color: var(--signal); }

.footer-strip__legal {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
  text-align: right;
}

/* ============================================================
   Page header (dark variant for Features / Security)
   ============================================================ */

.page-header {
  padding-top: 120px;
  padding-bottom: 96px;
  background: var(--white);
  border-bottom: 1px solid var(--grid);
}

.page-header--dark {
  background: var(--void);
  color: var(--white);
  border-bottom: 0;
}
.page-header--dark .headline-section { color: var(--white); }
.page-header--dark .subheadline { color: #9A9A9A; }

.page-header--ink {
  background: var(--ink);
  color: var(--white);
  border-bottom: 0;
}
.page-header--ink .headline-section { color: var(--white); }
.page-header--ink .subheadline { color: #9A9A9A; }

.page-header__grid-split {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 64px;
  align-items: center;
}

.page-header__copy { max-width: 720px; }

.page-header__headline {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 56px;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0;
}

.page-header__headline--xl {
  font-size: 68px;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.page-header__rule {
  height: 1px;
  background: rgba(222,222,222,0.4);
  width: 100%;
  margin: 0 0 24px;
  max-width: 320px;
}

/* ============================================================
   Comparison (features page)
   ============================================================ */

.compare {
  background: var(--ink);
  color: var(--white);
  padding-top: 104px;
  padding-bottom: 104px;
}

.compare__head { max-width: 720px; }
.compare__head .headline-section { color: var(--white); }

.compare__body {
  font-size: 17px;
  line-height: 1.65;
  color: #B0B0B0;
  max-width: 600px;
  margin: 24px 0 48px;
}

.compare-table {
  width: 100%;
  border-collapse: collapse;
}

.compare-table th,
.compare-table td {
  text-align: left;
  padding: 18px 20px;
  vertical-align: middle;
}

.compare-table thead th {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 500;
  border-bottom: 1px solid var(--dark-rule);
}

.compare-table thead th:first-child { color: var(--white); }
.compare-table thead .nullpoint { color: var(--verified); }
.compare-table thead .legacy { color: var(--slate); }

.compare-table tbody tr {
  border-bottom: 1px solid var(--dark-rule);
}
.compare-table tbody tr:nth-child(odd) {
  background: rgba(255,255,255,0.04);
}

.compare-table .feature-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 16px;
  color: var(--white);
}

.compare-table .nullpoint-cell,
.compare-table .legacy-cell {
  font-family: var(--font-mono);
  font-size: 13px;
}

.compare-table .nullpoint-cell {
  color: var(--verified);
}
.compare-table .nullpoint-cell::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  background: var(--verified);
  border-radius: 50%;
  margin-right: 8px;
  vertical-align: middle;
}

.compare-table .legacy-cell {
  color: var(--slate);
}
.compare-table .legacy-cell::before {
  content: "—";
  color: var(--slate);
  margin-right: 8px;
}

.compare__cta { margin-top: 40px; }
.compare__cta .btn { color: var(--white); border-color: var(--white); }
.compare__cta .btn:hover { color: var(--signal); border-color: var(--signal); }

/* ============================================================
   Enterprise feature grid + diagram
   ============================================================ */

.enterprise-feature {
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 48px;
  align-items: center;
  margin-top: 48px;
}

.enterprise-feature__cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.enterprise-feature__cards .feature-card-mini {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
}

.feature-card-mini__icon {
  width: 20px;
  height: 20px;
  border: 1.5px solid var(--slate);
  margin-bottom: 12px;
}

.feature-card-mini__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  color: var(--void);
  margin: 0 0 8px;
}

.feature-card-mini__desc {
  font-size: 15px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0;
}

.feature-card-mini__compliance {
  display: inline-block;
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--verified);
  border: 1px solid var(--verified);
  padding: 3px 7px;
}

/* Architectural diagram */
.arch-diagram {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
  display: grid;
  gap: 12px;
}

.arch-diagram__zone {
  border: 1.5px solid var(--void);
  padding: 14px 16px;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--void);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.arch-diagram__arrow {
  text-align: center;
  color: var(--slate);
  font-family: var(--font-mono);
  font-size: 14px;
}

.arch-diagram__caption {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-align: center;
}

/* ============================================================
   Timeline (enterprise)
   ============================================================ */

.timeline {
  position: relative;
  margin-top: 56px;
  padding-left: 64px;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 12px;
  bottom: 12px;
  width: 2px;
  background: var(--signal);
}

.timeline__item {
  position: relative;
  padding-bottom: 48px;
}

.timeline__item:last-child { padding-bottom: 0; }

.timeline__node {
  position: absolute;
  left: -56px;
  top: -2px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--signal);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 13px;
  color: var(--white);
}

.timeline__phase {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--signal);
  margin-bottom: 6px;
}

.timeline__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--void);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}

.timeline__desc {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  color: var(--slate);
  margin: 0;
  max-width: 640px;
}

/* ============================================================
   Enterprise CTA with mockup
   ============================================================ */

.cta-split {
  background: var(--ink);
  color: var(--white);
  padding-top: 100px;
  padding-bottom: 100px;
}

.cta-split__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.cta-split__copy .headline-section {
  color: var(--white);
  font-size: 52px;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.cta-split__sub {
  color: var(--grid);
  margin-top: 24px;
  font-size: 18px;
  max-width: 520px;
}

.cta-split__cta-row {
  margin-top: 40px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Dashboard mockup */
.dash-mock {
  position: relative;
  background: var(--void);
  border: 1px solid var(--slate);
  box-shadow: 8px 8px 0 var(--signal);
  padding: 18px;
  display: grid;
  grid-template-columns: 110px 1fr 130px;
  gap: 14px;
  font-family: var(--font-mono);
  color: var(--grid);
  font-size: 10px;
}

.dash-mock__sidebar,
.dash-mock__stream,
.dash-mock__compliance {
  border: 1px solid var(--dark-rule);
  padding: 12px;
}

.dash-mock__sidebar h6,
.dash-mock__stream h6,
.dash-mock__compliance h6 {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--signal);
  margin: 0 0 10px;
}

.dash-mock__sidebar ul,
.dash-mock__stream ul,
.dash-mock__compliance ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.dash-mock__sidebar li {
  color: var(--white);
  font-size: 10px;
}

.dash-mock__stream li {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--white);
  border-bottom: 1px dashed var(--dark-rule);
  padding-bottom: 4px;
}

.dash-mock__stream li:last-child { border: 0; }
.dash-mock__stream li time { color: var(--slate); }

.dash-mock__compliance li {
  color: var(--verified);
  display: flex;
  justify-content: space-between;
  font-size: 10px;
}

.dash-mock__caption {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--grid);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* ============================================================
   Security: stack diagram, certifications, story
   ============================================================ */

.stack-diagram {
  position: relative;
  padding-left: 12px;
  border-left: 2px solid var(--signal);
  display: grid;
  gap: 8px;
  width: 380px;
  max-width: 100%;
  margin-left: auto;
}

.stack-diagram__band {
  border: 1px solid var(--grid);
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--white);
  background: var(--ink);
}

.stack-diagram__band:nth-child(odd) {
  background: var(--ink-soft);
}

.stack-diagram__band .label { color: var(--signal); }
.stack-diagram__band .desc { color: var(--grid); }

/* Security feature grid */
.security-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--grid);
  border: 1px solid var(--grid);
  margin-top: 40px;
}

.security-feature {
  background: var(--white);
  padding: 28px 28px 28px;
  position: relative;
}

.security-feature::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--signal);
}

.security-feature__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  color: var(--void);
  letter-spacing: -0.01em;
  margin: 12px 0 8px;
}

.security-feature__desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--slate);
  margin: 0;
}

/* Cert grid */
.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 40px;
}

.cert-card {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 28px;
  position: relative;
}

.cert-card__top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.cert-card__icon {
  width: 32px;
  height: 32px;
  color: var(--void);
  flex-shrink: 0;
}

.cert-status {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  background: var(--verified);
  color: #fff;
  display: inline-block;
}

.cert-status--pending {
  background: var(--grid);
  color: var(--slate);
}

.cert-card__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--void);
  margin: 12px 0 6px;
}

.cert-card__meta {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin: 0 0 10px;
}

.cert-card__desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--slate);
  margin: 0;
}

/* Story block (security philosophy) */
.story {
  background: var(--white);
  padding-top: 120px;
  padding-bottom: 120px;
  border-top: 1px solid var(--grid);
}

.story__inner {
  max-width: 720px;
}

.story__head {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 40px;
  color: var(--void);
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin: 0;
}

.story__body {
  margin-top: 28px;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--slate);
}

.story__pullquote {
  margin-top: 24px;
  border-top: 1px solid var(--grid);
  padding-top: 24px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  color: var(--void);
}

.story__links {
  margin-top: 24px;
  display: flex;
  gap: 32px;
  flex-wrap: wrap;
}

/* Security CTA panel (signal top border) */
.cta-panel--signal-top {
  border-top: 2px solid var(--signal);
}

/* ============================================================
   Contact page
   ============================================================ */

.contact-options {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.option-card {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 32px;
  position: relative;
  display: flex;
  flex-direction: column;
}

.option-card__title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 20px;
  color: var(--void);
  margin: 0 0 12px;
  letter-spacing: -0.01em;
}

.option-card__desc {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0 0 20px;
  flex-grow: 1;
}

.option-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.meta-pill {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--slate);
  background: var(--mist);
  border: 1px solid var(--grid);
  padding: 4px 8px;
}

.meta-pill--verified {
  border-left: 2px solid var(--verified);
}

.option-card__arrow {
  position: absolute;
  bottom: 18px;
  right: 18px;
  color: var(--signal);
  font-family: var(--font-mono);
  font-size: 16px;
}

/* Contact form layout */
.contact-form-section {
  background: var(--white);
  padding-top: 112px;
  padding-bottom: 112px;
}

.contact-form-grid {
  display: grid;
  grid-template-columns: 7fr 4fr;
  gap: 64px;
  align-items: stretch;
}

.contact-form { display: grid; gap: 20px; margin-top: 32px; }

.form-field {
  display: grid;
  gap: 8px;
}

.form-field label {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
}

.form-field label .req {
  color: var(--signal);
  margin-left: 4px;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  height: 48px;
  padding: 0 14px;
  border: 1px solid var(--grid);
  background: var(--white);
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--void);
  border-radius: 0;
}

.form-field textarea {
  height: auto;
  min-height: 140px;
  padding: 14px;
  resize: vertical;
  font-family: var(--font-body);
  line-height: 1.6;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  outline: 0;
  border: 2px solid var(--void);
}

.form-help {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: none;
  letter-spacing: 0.04em;
}

.form-submit {
  background: var(--signal);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  height: 52px;
  border: 0;
  margin-top: 12px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.form-submit:hover { background: #B8001A; }

/* Trust sidebar */
.trust-sidebar {
  background: var(--mist);
  border-left: 1px solid var(--grid);
  padding: 28px;
  display: grid;
  gap: 24px;
  align-self: stretch;
}

.trust-sidebar__label {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
  margin: 0 0 8px;
}

.trust-sidebar__text {
  font-size: 13px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0;
}

.trust-sidebar hr {
  border: 0;
  border-top: 1px solid var(--grid);
  margin: 0;
}

.trust-sidebar__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--void);
}

.trust-sidebar__list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.trust-sidebar__list .sla {
  color: var(--verified);
}

.trust-sidebar__shield {
  display: inline-block;
  margin-right: 6px;
  color: var(--verified);
}

/* Story block on contact (dark) */
.story-dark {
  background: var(--ink);
  color: var(--white);
  padding-top: 96px;
  padding-bottom: 96px;
}

.story-dark__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.story-dark__head {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 36px;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin: 0;
  color: var(--white);
}

.story-dark__body {
  margin-top: 24px;
  font-size: 16px;
  line-height: 1.7;
  color: #C8C8C8;
  max-width: 520px;
}

/* FAQ */
.faq-grid {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 48px;
  margin-top: 48px;
  border-top: 1px solid var(--grid);
  padding-top: 48px;
}

.faq-grid__label {
  position: relative;
}

.faq-grid__icon {
  margin-top: 32px;
  color: var(--signal);
  width: 48px;
  height: 48px;
}

.faq-list {
  border-top: 1px solid var(--grid);
  border-left: 1px solid var(--grid);
  padding-left: 48px;
}

.faq-item {
  border-bottom: 1px solid var(--grid);
  padding: 28px 0;
  position: relative;
}

.faq-item__q {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 17px;
  color: var(--void);
  line-height: 1.3;
  margin: 0;
  padding-right: 32px;
}

.faq-item__a {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--slate);
  line-height: 1.65;
  margin: 8px 0 0;
}

.faq-item__plus {
  position: absolute;
  top: 28px;
  right: 0;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--grid);
}

/* Site footer */
.site-footer {
  background: var(--ink);
  color: var(--white);
  border-top: 2px solid var(--signal);
  padding-top: 48px;
  padding-bottom: 48px;
}

.site-footer__inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}

.site-footer__brand {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--white);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.site-footer__links {
  font-family: var(--font-body);
  font-size: 13px;
  color: #C8C8C8;
  text-align: center;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  justify-content: center;
}
.site-footer__links a {
  color: #C8C8C8;
  border-bottom: 1px solid transparent;
}
.site-footer__links a:hover { border-bottom-color: var(--signal); }

.site-footer__legal {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-align: right;
}

/* ============================================================
   Responsive
   ============================================================ */

@media (max-width: 1024px) {
  :root { --page-pad: 40px; }

  .hero__headline { font-size: 56px; }
  .headline-section { font-size: 40px; }
  .headline-section--xl { font-size: 44px; }
  .page-header__headline { font-size: 44px; }
  .page-header__headline--xl { font-size: 52px; }

  .hero__grid { grid-template-columns: 6fr 6fr; gap: 32px; }
  .page-header__grid-split { grid-template-columns: 6fr 6fr; gap: 32px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-dark .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-dark .stat { border-bottom: 1px solid var(--slate); }

  .feature-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid--two { grid-template-columns: repeat(2, 1fr); }
  .testimonials-grid { grid-template-columns: repeat(2, 1fr); }

  .enterprise-feature { grid-template-columns: 1fr; }
  .enterprise-feature__cards { grid-template-columns: repeat(2, 1fr); }

  .compare-table { font-size: 14px; }

  .security-features { grid-template-columns: repeat(2, 1fr); }
  .cert-grid { grid-template-columns: repeat(2, 1fr); }

  .contact-options { grid-template-columns: 1fr; }
  .contact-form-grid { grid-template-columns: 1fr; gap: 32px; }
  .trust-sidebar { border-left: 0; border-top: 1px solid var(--grid); }
  .story-dark__grid { grid-template-columns: 1fr; gap: 48px; }
  .faq-grid { grid-template-columns: 1fr; gap: 32px; }
  .faq-list { border-left: 0; padding-left: 0; }

  .cta-split__grid { grid-template-columns: 1fr; gap: 48px; }
  .cta-split__copy .headline-section { font-size: 40px; }

  .features-head { flex-direction: column; align-items: flex-start; }

  .stack-diagram { margin-left: 0; width: 100%; }
}

@media (max-width: 720px) {
  :root { --page-pad: 24px; --nav-height: 60px; }

  body { padding-top: var(--nav-height); }
  .nav__links { display: none; }
  .nav__toggle { display: inline-block; }
  .nav__cta { display: none; }
  .nav.is-open .nav__links {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--void);
    border-bottom: 1px solid var(--grid);
    padding: 16px 24px;
    align-items: stretch;
  }
  .nav.is-open .nav__link { padding: 12px 0; border-bottom: 1px solid var(--slate); }

  .hero__grid { grid-template-columns: 1fr; gap: 32px; }
  .page-header__grid-split { grid-template-columns: 1fr; gap: 32px; }

  .hero__headline { font-size: 40px; }
  .page-header__headline { font-size: 36px; }
  .page-header__headline--xl { font-size: 36px; }
  .headline-section, .headline-section--xl { font-size: 32px; }
  .cta-panel__head { font-size: 36px; }
  .story__head { font-size: 30px; }
  .story-dark__head { font-size: 28px; }
  .cta-split__copy .headline-section { font-size: 30px; }

  .section { padding-top: 64px; padding-bottom: 64px; }
  .hero { padding-top: 80px; padding-bottom: 64px; }
  .page-header { padding-top: 80px; padding-bottom: 64px; }
  .stats { padding-top: 56px; padding-bottom: 56px; }
  .stats__grid { grid-template-columns: 1fr; }
  .stats-dark .stats__grid { grid-template-columns: 1fr; }
  .stat { border-right: 0; }

  .feature-grid, .feature-grid--two { grid-template-columns: 1fr; }
  .testimonials-grid { grid-template-columns: 1fr; }

  .enterprise-feature__cards { grid-template-columns: 1fr; }

  .compare-table thead { display: none; }
  .compare-table, .compare-table tbody, .compare-table tr, .compare-table td { display: block; width: 100%; }
  .compare-table tr {
    padding: 16px 0;
    border-bottom: 1px solid var(--dark-rule);
    background: transparent;
  }
  .compare-table tr:nth-child(odd) { background: rgba(255,255,255,0.03); padding: 16px; }
  .compare-table td { padding: 6px 0; }
  .compare-table .feature-name { padding-bottom: 8px; }
  .compare-table .nullpoint-cell::after,
  .compare-table .legacy-cell::after {}

  .timeline { padding-left: 40px; }
  .timeline__node { left: -40px; width: 28px; height: 28px; font-size: 11px; }

  .security-features { grid-template-columns: 1fr; }
  .cert-grid { grid-template-columns: 1fr; }

  .footer-strip { grid-template-columns: 1fr; text-align: center; }
  .footer-strip__legal, .footer-strip__links { text-align: center; }

  .site-footer__inner { grid-template-columns: 1fr; text-align: center; }
  .site-footer__legal { text-align: center; }

  .cta-panel__cta-row .btn { width: 100%; }
  .cta-row .btn { width: 100%; }

  .dash-mock { grid-template-columns: 1fr; box-shadow: 6px 6px 0 var(--signal); }
}

tool_use_result.content:
/* ============================================================
   Nullpoint — Privacy-First Analytics
   Swiss Modern design system
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --void: #0A0A0A;
  --white: #F5F5F5;
  --signal: #E5001A;
  --slate: #4A4A4A;
  --grid: #DEDEDE;
  --mist: #F0F0F0;
  --ink: #1A1A2E;
  --verified: #00875A;
  --ink-soft: #1E2240;
  --dark-rule: #2E2E4A;

  --font-heading: 'Archivo', system-ui, -apple-system, Segoe UI, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, Segoe UI, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, Menlo, Consolas, monospace;

  --max-width: 1280px;
  --page-pad: 80px;
  --nav-height: 64px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--white);
  color: var(--void);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding-top: var(--nav-height);
}

a {
  color: inherit;
  text-decoration: none;
}

img,
svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
}

/* ============================================================
   Layout
   ============================================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-left: var(--page-pad);
  padding-right: var(--page-pad);
}

.section {
  padding-top: 96px;
  padding-bottom: 96px;
  position: relative;
}

.section--mist  { background: var(--mist); }
.section--white { background: var(--white); }
.section--ink   { background: var(--ink); color: var(--white); }
.section--void  { background: var(--void); color: var(--white); }

.section__rule-top {
  border-top: 1px solid var(--grid);
}
.section__rule-bottom {
  border-bottom: 1px solid var(--grid);
}

/* ============================================================
   Typography helpers
   ============================================================ */

.eyebrow {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--signal);
  margin: 0 0 16px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.eyebrow--centered {
  display: flex;
  justify-content: center;
}

.eyebrow--bar::before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 2px;
  background: var(--signal);
}

.eyebrow--slate { color: var(--slate); }

.headline-display {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 72px;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin: 0;
  color: var(--void);
}

.headline-section {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 48px;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0;
  color: var(--void);
}

.headline-section--white { color: var(--white); }
.headline-section--xl { font-size: 56px; font-weight: 800; }
.headline-section--md { font-size: 40px; }
.headline-section--sm { font-size: 36px; }

.subheadline {
  font-family: var(--font-body);
  font-size: 18px;
  line-height: 1.65;
  color: var(--slate);
  margin: 24px 0 0;
  max-width: 60ch;
}

.subheadline--white { color: #C8C8C8; }
.subheadline--mute { color: #9A9A9A; }

.body-prose {
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--slate);
  max-width: 68ch;
}

.body-prose--white { color: #B0B0B0; }
.body-prose code,
.body-prose .mono-inline {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--void);
  background: transparent;
}

/* ============================================================
   CTA buttons & links
   ============================================================ */

.cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 40px;
}

.cta-row--center {
  justify-content: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  height: 48px;
  padding: 0 24px;
  border: 1.5px solid transparent;
  border-radius: 0;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}

.btn--primary {
  background: var(--signal);
  color: #fff;
  border-color: var(--signal);
}
.btn--primary:hover { background: #FF1A30; border-color: #FF1A30; }

.btn--secondary {
  background: transparent;
  color: var(--void);
  border-color: var(--void);
}
.btn--secondary:hover { color: var(--signal); border-color: var(--signal); }

.btn--ghost-light {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn--ghost-light:hover { color: var(--signal); border-color: var(--signal); }

.btn--ghost-grid {
  background: transparent;
  color: var(--white);
  border-color: var(--grid);
}
.btn--ghost-grid:hover { color: var(--signal); border-color: var(--signal); }

.btn--lg { height: 52px; padding: 0 32px; min-width: 180px; }
.btn--block { width: 100%; }

.text-link {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 14px;
  color: var(--void);
  border-bottom: 1px solid var(--void);
  padding-bottom: 2px;
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  white-space: nowrap;
}
.text-link__arrow { color: var(--signal); }
.text-link:hover { border-color: var(--signal); }

.editorial-link {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 15px;
  color: var(--signal);
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.editorial-link:hover { border-bottom-color: var(--signal); }
.editorial-link__arrow {
  font-family: var(--font-mono);
}

/* ============================================================
   Navigation
   ============================================================ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: var(--void);
  border-bottom: 1px solid var(--grid);
  z-index: 1000;
}

.nav__inner {
  height: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--white);
  font-size: 18px;
  letter-spacing: -0.01em;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.nav__logo-mark {
  width: 18px;
  height: 18px;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
  margin-left: auto;
}

.nav__link {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--white);
  padding: 6px 0;
  border-bottom: 1px solid transparent;
  transition: border-color 0.15s ease, color 0.15s ease;
}

.nav__link:hover { border-bottom-color: var(--signal); }
.nav__link.is-active { border-bottom-color: var(--signal); color: var(--white); }

.nav__cta {
  margin-left: 12px;
  background: var(--signal);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 9px 16px;
  border: 0;
  border-radius: 999px;
}

.nav__cta:hover { background: #FF1A30; }

.nav__toggle {
  display: none;
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
  padding: 6px 10px;
  font-family: var(--font-mono);
  font-size: 12px;
  cursor: pointer;
  margin-left: auto;
}

/* ============================================================
   Hero (home)
   ============================================================ */

.hero {
  background: var(--white);
  padding-top: 120px;
  padding-bottom: 96px;
  border-bottom: 1px solid var(--grid);
}

.hero__grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 64px;
  align-items: center;
}

.hero__copy { max-width: 600px; }

.hero__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 72px;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin: 0;
}

.hero__sub {
  margin-top: 24px;
  max-width: 520px;
  font-size: 18px;
  color: var(--slate);
}

/* Hero illustration (analytics dashboard mock) */
.hero-mock {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
  display: grid;
  gap: 16px;
}

.hero-mock__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
  border-bottom: 1px solid var(--grid);
  padding-bottom: 12px;
}

.hero-mock__head strong {
  color: var(--void);
  font-weight: 700;
}

.hero-mock__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.hero-mock__metric {
  border: 1px solid var(--grid);
  padding: 10px 12px;
}

.hero-mock__metric .num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 18px;
  color: var(--void);
  display: block;
}

.hero-mock__metric .lbl {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--slate);
}

.hero-mock__metric--accent .num { color: var(--signal); }

.hero-mock__chart {
  border: 1px solid var(--grid);
  padding: 16px 18px 12px;
}

.hero-mock__chart-title {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--slate);
  margin-bottom: 12px;
  display: flex;
  justify-content: space-between;
}

.hero-mock__chart-title em {
  font-style: normal;
  color: var(--signal);
  font-weight: 700;
}

.hero-mock__funnel {
  display: grid;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
}

.hero-mock__bar {
  position: relative;
  height: 22px;
  background: var(--mist);
  border-left: 2px solid var(--signal);
}

.hero-mock__bar > span {
  position: absolute;
  inset: 0 auto 0 0;
  background: rgba(229,0,26,0.12);
}

.hero-mock__bar > b {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--void);
  font-weight: 700;
}

/* ============================================================
   Stats
   ============================================================ */

.stats {
  background: var(--mist);
  border-top: 1px solid var(--grid);
  border-bottom: 1px solid var(--grid);
  padding-top: 80px;
  padding-bottom: 80px;
}

.stats__head { text-align: center; }
.stats__head .eyebrow { justify-content: center; display: flex; }
.stats__head .headline-section--sm { margin: 8px auto 0; }
.stats__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 56px;
  border-top: 1px solid var(--grid);
}

.stat {
  padding: 32px;
  border-right: 1px solid var(--grid);
  border-bottom: 1px solid var(--grid);
}
.stat:last-child { border-right: 0; }

.stat__num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 48px;
  color: var(--void);
  letter-spacing: -0.01em;
  line-height: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat__num--signal { color: var(--signal); }
.stat__num--verified { color: var(--verified); font-size: 28px; }

.stat__num svg { flex-shrink: 0; }

.stat__desc {
  margin-top: 12px;
  font-size: 14px;
  color: var(--slate);
  line-height: 1.5;
  font-family: var(--font-body);
}

/* Dark stats variant (enterprise) */
.stats-dark {
  background: var(--void);
  color: var(--white);
}

.stats-dark .stats__head { text-align: left; }
.stats-dark .stats__head .eyebrow { display: inline-flex; }
.stats-dark .stats__grid {
  border: 0;
  margin-top: 48px;
  grid-template-columns: repeat(4, 1fr);
}

.stats-dark .stat {
  border-right: 1px solid var(--slate);
  border-bottom: 0;
}
.stats-dark .stat:last-child { border-right: 0; }

.stats-dark .stat__num {
  color: var(--white);
  font-size: 56px;
}
.stats-dark .stat__desc { color: var(--grid); }

/* ============================================================
   Feature grid
   ============================================================ */

.features-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 32px;
  margin-bottom: 56px;
}

.features-head__title { max-width: 640px; }
.features-head__title .headline-section { margin-top: 8px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
}

.feature-grid--two {
  grid-template-columns: repeat(2, 1fr);
}

.feature-card {
  background: var(--white);
  border: 2px solid var(--grid);
  padding: 32px;
  position: relative;
  margin-left: -1px;
  margin-top: -1px;
}

.feature-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 2px;
  height: 32px;
  background: var(--signal);
}

.feature-card--lead::before { height: 48px; }

.feature-card__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.01em;
  color: var(--void);
  margin: 16px 0 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.feature-card__title .verified-dot {
  width: 8px;
  height: 8px;
  background: var(--verified);
  border-radius: 50%;
  display: inline-block;
}

.feature-card__desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--slate);
  margin: 8px 0 0;
}

.code-chip {
  display: inline-block;
  margin-top: 16px;
  padding: 6px 10px;
  background: var(--mist);
  border: 1px solid var(--grid);
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
}

/* Feature card with tag (features page) */
.feature-card--tagged {
  border: 1px solid var(--grid);
  background: var(--white);
}
.feature-card--tagged::before { display: none; }

.tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--signal);
  border: 1px solid var(--signal);
  border-radius: 2px;
  padding: 4px 8px;
  margin-bottom: 16px;
}

.tag--verified {
  color: var(--verified);
  border-color: var(--verified);
}

/* Compliance feature card with icon */
.feature-card--icon {
  border: 1px solid var(--grid);
  background: var(--white);
}
.feature-card--icon::before { display: none; }

.feature-card__icon {
  width: 32px;
  height: 32px;
  margin-bottom: 16px;
  color: var(--void);
}

/* ============================================================
   Testimonials
   ============================================================ */

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--mist);
  border: 1px solid var(--grid);
  padding: 32px;
}

.testimonial-card__quote-mark {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 64px;
  color: var(--signal);
  line-height: 1;
  margin-bottom: -8px;
  display: block;
}

.testimonial-card__quote {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  color: var(--void);
  font-style: italic;
  margin: 0;
}

.testimonial-card__divider {
  border: 0;
  border-top: 1px solid var(--grid);
  margin: 24px 0 16px;
}

.testimonial-card__attr {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--slate);
  margin: 0;
}

.testimonial-card__attr strong {
  color: var(--slate);
  font-weight: 600;
  display: block;
}

/* ============================================================
   CTA panel (dark)
   ============================================================ */

.cta-panel {
  background: var(--ink);
  color: var(--white);
  padding-top: 112px;
  padding-bottom: 112px;
  position: relative;
  overflow: hidden;
}

.cta-panel--pattern::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(245,245,245,0.10) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
}

.cta-panel__inner {
  position: relative;
  text-align: center;
}

.cta-panel__inner .eyebrow {
  display: flex;
  justify-content: center;
}

.cta-panel__head {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 56px;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--white);
  max-width: 720px;
  margin: 8px auto 0;
}

.cta-panel__sub {
  margin: 16px auto 0;
  max-width: 480px;
  color: #A0A0B8;
  font-size: 16px;
}

.cta-panel__cta-row {
  margin-top: 48px;
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

/* Footer strip inside ink panel */
.footer-strip {
  position: relative;
  margin-top: 64px;
  padding-top: 24px;
  border-top: 1px solid rgba(222,222,222,0.2);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}

.footer-strip__brand {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--white);
}

.footer-strip__links {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
  text-align: center;
}

.footer-strip__links a {
  color: var(--grid);
  border-bottom: 1px solid transparent;
}
.footer-strip__links a:hover { border-bottom-color: var(--signal); }

.footer-strip__legal {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate);
  text-align: right;
}

/* ============================================================
   Page header (dark variant for Features / Security)
   ============================================================ */

.page-header {
  padding-top: 120px;
  padding-bottom: 96px;
  background: var(--white);
  border-bottom: 1px solid var(--grid);
}

.page-header--dark {
  background: var(--void);
  color: var(--white);
  border-bottom: 0;
}
.page-header--dark .headline-section { color: var(--white); }
.page-header--dark .subheadline { color: #9A9A9A; }

.page-header--ink {
  background: var(--ink);
  color: var(--white);
  border-bottom: 0;
}
.page-header--ink .headline-section { color: var(--white); }
.page-header--ink .subheadline { color: #9A9A9A; }

.page-header__grid-split {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 64px;
  align-items: center;
}

.page-header__copy { max-width: 720px; }

.page-header__headline {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 56px;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0;
}

.page-header__headline--xl {
  font-size: 68px;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.page-header__rule {
  height: 1px;
  background: rgba(222,222,222,0.4);
  width: 100%;
  margin: 0 0 24px;
  max-width: 320px;
}

/* ============================================================
   Comparison (features page)
   ============================================================ */

.compare {
  background: var(--ink);
  color: var(--white);
  padding-top: 104px;
  padding-bottom: 104px;
}

.compare__head { max-width: 720px; }
.compare__head .headline-section { color: var(--white); }

.compare__body {
  font-size: 17px;
  line-height: 1.65;
  color: #B0B0B0;
  max-width: 600px;
  margin: 24px 0 48px;
}

.compare-table {
  width: 100%;
  border-collapse: collapse;
}

.compare-table th,
.compare-table td {
  text-align: left;
  padding: 18px 20px;
  vertical-align: middle;
}

.compare-table thead th {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 500;
  border-bottom: 1px solid var(--dark-rule);
}

.compare-table thead th:first-child { color: var(--white); }
.compare-table thead .nullpoint { color: var(--verified); }
.compare-table thead .legacy { color: var(--slate); }

.compare-table tbody tr {
  border-bottom: 1px solid var(--dark-rule);
}
.compare-table tbody tr:nth-child(odd) {
  background: rgba(255,255,255,0.04);
}

.compare-table .feature-name {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 16px;
  color: var(--white);
}

.compare-table .nullpoint-cell,
.compare-table .legacy-cell {
  font-family: var(--font-mono);
  font-size: 13px;
}

.compare-table .nullpoint-cell {
  color: var(--verified);
}
.compare-table .nullpoint-cell::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  background: var(--verified);
  border-radius: 50%;
  margin-right: 8px;
  vertical-align: middle;
}

.compare-table .legacy-cell {
  color: var(--slate);
}
.compare-table .legacy-cell::before {
  content: "—";
  color: var(--slate);
  margin-right: 8px;
}

.compare__cta { margin-top: 40px; }
.compare__cta .btn { color: var(--white); border-color: var(--white); }
.compare__cta .btn:hover { color: var(--signal); border-color: var(--signal); }

/* ============================================================
   Enterprise feature grid + diagram
   ============================================================ */

.enterprise-feature {
  display: grid;
  grid-template-columns: 8fr 4fr;
  gap: 48px;
  align-items: center;
  margin-top: 48px;
}

.enterprise-feature__cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.enterprise-feature__cards .feature-card-mini {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
}

.feature-card-mini__icon {
  width: 20px;
  height: 20px;
  border: 1.5px solid var(--slate);
  margin-bottom: 12px;
}

.feature-card-mini__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  color: var(--void);
  margin: 0 0 8px;
}

.feature-card-mini__desc {
  font-size: 15px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0;
}

.feature-card-mini__compliance {
  display: inline-block;
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--verified);
  border: 1px solid var(--verified);
  padding: 3px 7px;
}

/* Architectural diagram */
.arch-diagram {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 24px;
  display: grid;
  gap: 12px;
}

.arch-diagram__zone {
  border: 1.5px solid var(--void);
  padding: 14px 16px;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--void);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.arch-diagram__arrow {
  text-align: center;
  color: var(--slate);
  font-family: var(--font-mono);
  font-size: 14px;
}

.arch-diagram__caption {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-align: center;
}

/* ============================================================
   Timeline (enterprise)
   ============================================================ */

.timeline {
  position: relative;
  margin-top: 56px;
  padding-left: 64px;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 12px;
  bottom: 12px;
  width: 2px;
  background: var(--signal);
}

.timeline__item {
  position: relative;
  padding-bottom: 48px;
}

.timeline__item:last-child { padding-bottom: 0; }

.timeline__node {
  position: absolute;
  left: -56px;
  top: -2px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--signal);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 13px;
  color: var(--white);
}

.timeline__phase {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--signal);
  margin-bottom: 6px;
}

.timeline__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--void);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}

.timeline__desc {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  color: var(--slate);
  margin: 0;
  max-width: 640px;
}

/* ============================================================
   Enterprise CTA with mockup
   ============================================================ */

.cta-split {
  background: var(--ink);
  color: var(--white);
  padding-top: 100px;
  padding-bottom: 100px;
}

.cta-split__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.cta-split__copy .headline-section {
  color: var(--white);
  font-size: 52px;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.cta-split__sub {
  color: var(--grid);
  margin-top: 24px;
  font-size: 18px;
  max-width: 520px;
}

.cta-split__cta-row {
  margin-top: 40px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Dashboard mockup */
.dash-mock {
  position: relative;
  background: var(--void);
  border: 1px solid var(--slate);
  box-shadow: 8px 8px 0 var(--signal);
  padding: 18px;
  display: grid;
  grid-template-columns: 110px 1fr 130px;
  gap: 14px;
  font-family: var(--font-mono);
  color: var(--grid);
  font-size: 10px;
}

.dash-mock__sidebar,
.dash-mock__stream,
.dash-mock__compliance {
  border: 1px solid var(--dark-rule);
  padding: 12px;
}

.dash-mock__sidebar h6,
.dash-mock__stream h6,
.dash-mock__compliance h6 {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--signal);
  margin: 0 0 10px;
}

.dash-mock__sidebar ul,
.dash-mock__stream ul,
.dash-mock__compliance ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.dash-mock__sidebar li {
  color: var(--white);
  font-size: 10px;
}

.dash-mock__stream li {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--white);
  border-bottom: 1px dashed var(--dark-rule);
  padding-bottom: 4px;
}

.dash-mock__stream li:last-child { border: 0; }
.dash-mock__stream li time { color: var(--slate); }

.dash-mock__compliance li {
  color: var(--verified);
  display: flex;
  justify-content: space-between;
  font-size: 10px;
}

.dash-mock__caption {
  margin-top: 12px;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--grid);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* ============================================================
   Security: stack diagram, certifications, story
   ============================================================ */

.stack-diagram {
  position: relative;
  padding-left: 12px;
  border-left: 2px solid var(--signal);
  display: grid;
  gap: 8px;
  width: 380px;
  max-width: 100%;
  margin-left: auto;
}

.stack-diagram__band {
  border: 1px solid var(--grid);
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--white);
  background: var(--ink);
}

.stack-diagram__band:nth-child(odd) {
  background: var(--ink-soft);
}

.stack-diagram__band .label { color: var(--signal); }
.stack-diagram__band .desc { color: var(--grid); }

/* Security feature grid */
.security-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--grid);
  border: 1px solid var(--grid);
  margin-top: 40px;
}

.security-feature {
  background: var(--white);
  padding: 28px 28px 28px;
  position: relative;
}

.security-feature::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--signal);
}

.security-feature__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  color: var(--void);
  letter-spacing: -0.01em;
  margin: 12px 0 8px;
}

.security-feature__desc {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--slate);
  margin: 0;
}

/* Cert grid */
.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 40px;
}

.cert-card {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 28px;
  position: relative;
}

.cert-card__top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.cert-card__icon {
  width: 32px;
  height: 32px;
  color: var(--void);
  flex-shrink: 0;
}

.cert-status {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 4px 8px;
  background: var(--verified);
  color: #fff;
  display: inline-block;
}

.cert-status--pending {
  background: var(--grid);
  color: var(--slate);
}

.cert-card__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--void);
  margin: 12px 0 6px;
}

.cert-card__meta {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin: 0 0 10px;
}

.cert-card__desc {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--slate);
  margin: 0;
}

/* Story block (security philosophy) */
.story {
  background: var(--white);
  padding-top: 120px;
  padding-bottom: 120px;
  border-top: 1px solid var(--grid);
}

.story__inner {
  max-width: 720px;
}

.story__head {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 40px;
  color: var(--void);
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin: 0;
}

.story__body {
  margin-top: 28px;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.7;
  color: var(--slate);
}

.story__pullquote {
  margin-top: 24px;
  border-top: 1px solid var(--grid);
  padding-top: 24px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  color: var(--void);
}

.story__links {
  margin-top: 24px;
  display: flex;
  gap: 32px;
  flex-wrap: wrap;
}

/* Security CTA panel (signal top border) */
.cta-panel--signal-top {
  border-top: 2px solid var(--signal);
}

/* ============================================================
   Contact page
   ============================================================ */

.contact-options {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.option-card {
  background: var(--white);
  border: 1px solid var(--grid);
  padding: 32px;
  position: relative;
  display: flex;
  flex-direction: column;
}

.option-card__title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 20px;
  color: var(--void);
  margin: 0 0 12px;
  letter-spacing: -0.01em;
}

.option-card__desc {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0 0 20px;
  flex-grow: 1;
}

.option-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.meta-pill {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--slate);
  background: var(--mist);
  border: 1px solid var(--grid);
  padding: 4px 8px;
}

.meta-pill--verified {
  border-left: 2px solid var(--verified);
}

.option-card__arrow {
  position: absolute;
  bottom: 18px;
  right: 18px;
  color: var(--signal);
  font-family: var(--font-mono);
  font-size: 16px;
}

/* Contact form layout */
.contact-form-section {
  background: var(--white);
  padding-top: 112px;
  padding-bottom: 112px;
}

.contact-form-grid {
  display: grid;
  grid-template-columns: 7fr 4fr;
  gap: 64px;
  align-items: stretch;
}

.contact-form { display: grid; gap: 20px; margin-top: 32px; }

.form-field {
  display: grid;
  gap: 8px;
}

.form-field label {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
}

.form-field label .req {
  color: var(--signal);
  margin-left: 4px;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  height: 48px;
  padding: 0 14px;
  border: 1px solid var(--grid);
  background: var(--white);
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--void);
  border-radius: 0;
}

.form-field textarea {
  height: auto;
  min-height: 140px;
  padding: 14px;
  resize: vertical;
  font-family: var(--font-body);
  line-height: 1.6;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  outline: 0;
  border: 2px solid var(--void);
}

.form-help {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-transform: none;
  letter-spacing: 0.04em;
}

.form-submit {
  background: var(--signal);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  height: 52px;
  border: 0;
  margin-top: 12px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.form-submit:hover { background: #B8001A; }

/* Trust sidebar */
.trust-sidebar {
  background: var(--mist);
  border-left: 1px solid var(--grid);
  padding: 28px;
  display: grid;
  gap: 24px;
  align-self: stretch;
}

.trust-sidebar__label {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate);
  margin: 0 0 8px;
}

.trust-sidebar__text {
  font-size: 13px;
  color: var(--slate);
  line-height: 1.6;
  margin: 0;
}

.trust-sidebar hr {
  border: 0;
  border-top: 1px solid var(--grid);
  margin: 0;
}

.trust-sidebar__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--void);
}

.trust-sidebar__list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.trust-sidebar__list .sla {
  color: var(--verified);
}

.trust-sidebar__shield {
  display: inline-block;
  margin-right: 6px;
  color: var(--verified);
}

/* Story block on contact (dark) */
.story-dark {
  background: var(--ink);
  color: var(--white);
  padding-top: 96px;
  padding-bottom: 96px;
}

.story-dark__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.story-dark__head {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 36px;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin: 0;
  color: var(--white);
}

.story-dark__body {
  margin-top: 24px;
  font-size: 16px;
  line-height: 1.7;
  color: #C8C8C8;
  max-width: 520px;
}

/* FAQ */
.faq-grid {
  display: grid;
  grid-template-columns: 4fr 8fr;
  gap: 48px;
  margin-top: 48px;
  border-top: 1px solid var(--grid);
  padding-top: 48px;
}

.faq-grid__label {
  position: relative;
}

.faq-grid__icon {
  margin-top: 32px;
  color: var(--signal);
  width: 48px;
  height: 48px;
}

.faq-list {
  border-top: 1px solid var(--grid);
  border-left: 1px solid var(--grid);
  padding-left: 48px;
}

.faq-item {
  border-bottom: 1px solid var(--grid);
  padding: 28px 0;
  position: relative;
}

.faq-item__q {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 17px;
  color: var(--void);
  line-height: 1.3;
  margin: 0;
  padding-right: 32px;
}

.faq-item__a {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--slate);
  line-height: 1.65;
  margin: 8px 0 0;
}

.faq-item__plus {
  position: absolute;
  top: 28px;
  right: 0;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--grid);
}

/* Site footer */
.site-footer {
  background: var(--ink);
  color: var(--white);
  border-top: 2px solid var(--signal);
  padding-top: 48px;
  padding-bottom: 48px;
}

.site-footer__inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}

.site-footer__brand {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--white);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.site-footer__links {
  font-family: var(--font-body);
  font-size: 13px;
  color: #C8C8C8;
  text-align: center;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  justify-content: center;
}
.site-footer__links a {
  color: #C8C8C8;
  border-bottom: 1px solid transparent;
}
.site-footer__links a:hover { border-bottom-color: var(--signal); }

.site-footer__legal {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--slate);
  text-align: right;
}

/* ============================================================
   Responsive
   ============================================================ */

@media (max-width: 1024px) {
  :root { --page-pad: 40px; }

  .hero__headline { font-size: 56px; }
  .headline-section { font-size: 40px; }
  .headline-section--xl { font-size: 44px; }
  .page-header__headline { font-size: 44px; }
  .page-header__headline--xl { font-size: 52px; }

  .hero__grid { grid-template-columns: 6fr 6fr; gap: 32px; }
  .page-header__grid-split { grid-template-columns: 6fr 6fr; gap: 32px; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-dark .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-dark .stat { border-bottom: 1px solid var(--slate); }

  .feature-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-grid--two { grid-template-columns: repeat(2, 1fr); }
  .testimonials-grid { grid-template-columns: repeat(2, 1fr); }

  .enterprise-feature { grid-template-columns: 1fr; }
  .enterprise-feature__cards { grid-template-columns: repeat(2, 1fr); }

  .compare-table { font-size: 14px; }

  .security-features { grid-template-columns: repeat(2, 1fr); }
  .cert-grid { grid-template-columns: repeat(2, 1fr); }

  .contact-options { grid-template-columns: 1fr; }
  .contact-form-grid { grid-template-columns: 1fr; gap: 32px; }
  .trust-sidebar { border-left: 0; border-top: 1px solid var(--grid); }
  .story-dark__grid { grid-template-columns: 1fr; gap: 48px; }
  .faq-grid { grid-template-columns: 1fr; gap: 32px; }
  .faq-list { border-left: 0; padding-left: 0; }

  .cta-split__grid { grid-template-columns: 1fr; gap: 48px; }
  .cta-split__copy .headline-section { font-size: 40px; }

  .features-head { flex-direction: column; align-items: flex-start; }

  .stack-diagram { margin-left: 0; width: 100%; }
}

@media (max-width: 720px) {
  :root { --page-pad: 24px; --nav-height: 60px; }

  body { padding-top: var(--nav-height); }
  .nav__links { display: none; }
  .nav__toggle { display: inline-block; }
  .nav__cta { display: none; }
  .nav.is-open .nav__links {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--void);
    border-bottom: 1px solid var(--grid);
    padding: 16px 24px;
    align-items: stretch;
  }
  .nav.is-open .nav__link { padding: 12px 0; border-bottom: 1px solid var(--slate); }

  .hero__grid { grid-template-columns: 1fr; gap: 32px; }
  .page-header__grid-split { grid-template-columns: 1fr; gap: 32px; }

  .hero__headline { font-size: 40px; }
  .page-header__headline { font-size: 36px; }
  .page-header__headline--xl { font-size: 36px; }
  .headline-section, .headline-section--xl { font-size: 32px; }
  .cta-panel__head { font-size: 36px; }
  .story__head { font-size: 30px; }
  .story-dark__head { font-size: 28px; }
  .cta-split__copy .headline-section { font-size: 30px; }

  .section { padding-top: 64px; padding-bottom: 64px; }
  .hero { padding-top: 80px; padding-bottom: 64px; }
  .page-header { padding-top: 80px; padding-bottom: 64px; }
  .stats { padding-top: 56px; padding-bottom: 56px; }
  .stats__grid { grid-template-columns: 1fr; }
  .stats-dark .stats__grid { grid-template-columns: 1fr; }
  .stat { border-right: 0; }

  .feature-grid, .feature-grid--two { grid-template-columns: 1fr; }
  .testimonials-grid { grid-template-columns: 1fr; }

  .enterprise-feature__cards { grid-template-columns: 1fr; }

  .compare-table thead { display: none; }
  .compare-table, .compare-table tbody, .compare-table tr, .compare-table td { display: block; width: 100%; }
  .compare-table tr {
    padding: 16px 0;
    border-bottom: 1px solid var(--dark-rule);
    background: transparent;
  }
  .compare-table tr:nth-child(odd) { background: rgba(255,255,255,0.03); padding: 16px; }
  .compare-table td { padding: 6px 0; }
  .compare-table .feature-name { padding-bottom: 8px; }
  .compare-table .nullpoint-cell::after,
  .compare-table .legacy-cell::after {}

  .timeline { padding-left: 40px; }
  .timeline__node { left: -40px; width: 28px; height: 28px; font-size: 11px; }

  .security-features { grid-template-columns: 1fr; }
  .cert-grid { grid-template-columns: 1fr; }

  .footer-strip { grid-template-columns: 1fr; text-align: center; }
  .footer-strip__legal, .footer-strip__links { text-align: center; }

  .site-footer__inner { grid-template-columns: 1fr; text-align: center; }
  .site-footer__legal { text-align: center; }

  .cta-panel__cta-row .btn { width: 100%; }
  .cta-row .btn { width: 100%; }

  .dash-mock { grid-template-columns: 1fr; box-shadow: 6px 6px 0 var(--signal); }
}

input.content:
// Mobile nav toggle (visual only)
(function () {
  var nav = document.querySelector('.nav');
  if (!nav) return;
  var btn = nav.querySelector('.nav__toggle');
  if (!btn) return;
  btn.addEventListener('click', function () {
    nav.classList.toggle('is-open');
    btn.setAttribute(
      'aria-expanded',
      nav.classList.contains('is-open') ? 'true' : 'false'
    );
  });
})();

// Form prevent-default (visual only — no backend)
(function () {
  var form = document.querySelector('.contact-form');
  if (!form) return;
  form.addEventListener('submit', function (e) {
    e.preventDefault();
  });
})();

